            set
            {
                if (value)
                {
                    DocumentAdv document = null;
#if !WPF
                    UIDispatcher.Execute(() =>
                    {
#endif
                        document = Document;
#if !WPF
                    });
#endif
                    if (document != null)
                        document.ClearUnlinkedFields();
                }
                isDocumentLoaded = value;
            }
        }
