        /// <summary>
        /// Initializes the loading page popup.
        /// </summary>
        private void InitLoadingPagePopup()
        {
            CurrentLoadingPagePopup = new Grid() { VerticalAlignment = VerticalAlignment.Top, IsHitTestVisible = false };
            ColumnDefinition col1 = new ColumnDefinition();
            ColumnDefinition col2 = new ColumnDefinition();
            CurrentLoadingPagePopup.ColumnDefinitions.Add(col1);
            CurrentLoadingPagePopup.ColumnDefinitions.Add(col2);
            CurrentLoadingPageBlock = new TextBlock();
            CurrentLoadingPageBlock.FontSize = 45;
            CurrentLoadingPageBlock.Foreground = new SolidColorBrush(Color.FromArgb(255, 96, 96, 96));
            CurrentLoadingPageBlock.Text = "1";
            CurrentLoadingPageBlock.VerticalAlignment = VerticalAlignment.Center;
            CurrentLoadingPagePopup.Children.Add(CurrentLoadingPageBlock);
            Grid.SetColumn(CurrentLoadingPageBlock, 1);
            TextBlock textBlock = new TextBlock();
            textBlock.VerticalAlignment = VerticalAlignment.Center;
            textBlock.FontSize = 16;
            textBlock.Text = "Loading page";
            textBlock.TextWrapping = TextWrapping.Wrap;
            textBlock.TextAlignment = TextAlignmentEnum.Right;
            textBlock.Width = 80;
            textBlock.Foreground = new SolidColorBrush(Color.FromArgb(255, 96, 96, 96));
            CurrentLoadingPagePopup.Children.Add(textBlock);
            CurrentLoadingPagePopup.Visibility = Visibility.Collapsed;
        }
