        {
            copyIcon = new Grid() { Visibility = Visibility.Collapsed, VerticalAlignment = VerticalAlignment.Top, IsHitTestVisible = false, Width = 32, Height = 32 };
            Grid grid = new Grid() { VerticalAlignment = VerticalAlignment.Top, IsHitTestVisible = false, Width = 32, Height = 32};
