        /// <summary>
        /// Initializes the radial menu.
        /// </summary>
        private void InitRadialMenu()
        {
            radialMenu = new SfRadialMenu();
            radialMenu.Visibility = Visibility.Collapsed;
            radialMenu.EnableFreeRotation = false;
            radialMenu.CenterRimRadiusFactor = 0.18;
            radialMenu.Padding = new Thickness(5);
            radialMenu.RimHoverBrush = new SolidColorBrush(Color.FromArgb(0xFF, 0x46, 0x46, 0x46));
            radialMenu.RenderTransform = new CompositeTransform();
            RadialMenuIconGrid = new Grid();
            RadialMenuIconGrid.Background = new SolidColorBrush(Colors.Transparent);
            radialMenu.Icon = RadialMenuIconGrid;
            radialMenu.Opened += radialMenu_Opened;
            radialMenu.Closed += radialMenu_Closed;
            radialMenu.GotFocus += radialMenu_GotFocus;
            LoadDefaultRadialMenu();
        }
        /// <summary>
        /// Handles the GotFocus event of the RadialMenu control.
        /// </summary>
        /// <param name="sender">The source of the event.</param>
        /// <param name="e">The <see cref="RoutedEventArgs"/> instance containing the event data.</param>
        void radialMenu_GotFocus(object sender, RoutedEventArgs e)
        {
            if (e.OriginalSource is Button && (e.OriginalSource as Button).Content == RadialMenuIconGrid
                && radialMenuNavigateButton == null)
            {
                radialMenuNavigateButton = e.OriginalSource as Button;
                Focus(FocusState.Pointer);
                radialMenu.IsOpen = true;
            }
        }
        /// <summary>
        /// Handles the Opened event of the radialMenu control.
        /// </summary>
        /// <param name="sender">The source of the event.</param>
        /// <param name="e">The <see cref="RoutedEventArgs"/> instance containing the event data.</param>
        void radialMenu_Opened(object sender, RoutedEventArgs e)
        {
            if (e.OriginalSource is Button && (e.OriginalSource as Button).Content == RadialMenuIconGrid
                && radialMenuNavigateButton == null)
                radialMenuNavigateButton = e.OriginalSource as Button;
            Focus(FocusState.Pointer);
        }
        /// <summary>
        /// Handles the Closed event of the radialMenu control.
        /// </summary>
        /// <param name="sender">The source of the event.</param>
        /// <param name="e">The <see cref="RoutedEventArgs"/> instance containing the event data.</param>
        void radialMenu_Closed(object sender, RoutedEventArgs e)
        {
            if (e.OriginalSource is Button && (e.OriginalSource as Button).Content == RadialMenuIconGrid
                && radialMenuNavigateButton == null)
                radialMenuNavigateButton = e.OriginalSource as Button;
            IsPopItemVisible = false;
            fontPopup.Visibility = Visibility.Collapsed;
            Focus(FocusState.Pointer);
        }
        /// <summary>
        /// Loads the default radial menu.
        /// </summary>
        internal void LoadDefaultRadialMenu()
        {
            RadialMenuIconGrid.Children.Clear();
            RadialMenuIconGrid.Children.Add(XamlReader.Load(pathEdit) as Windows.UI.Xaml.Shapes.Path);
            radialMenu.Items.Clear();

            //Inserts image.
            SfRadialMenuItem menuItem = GetRadialMenuItem("Insert Image", "Insert Image", pathInsertPicture);
            menuItem.Command = InsertPictureCommand;
            radialMenu.Items.Add(menuItem);

            menuItem = GetRadialMenuItem("Hyperlink", "Insert Hyperlink", pathHyperlink);
            menuItem.Command = InsertHyperlinkCommand;
            radialMenu.Items.Add(menuItem);

            //Inserts Table.
            menuItem = GetRadialMenuItem("Insert\nTable", "Insert Table", pathInsertTable);
            menuItem.Command = InsertTableCommand;
            radialMenu.Items.Add(menuItem);

            //Applies list.
            radialMenu.Items.Add(LoadListMenuItem());

            //Pastes clipboard content.
            menuItem = GetRadialMenuItem("Paste", "Paste", pathPaste);
            menuItem.Command = PasteCommand;
            radialMenu.Items.Add(menuItem);

            //Undo Redo
            SfRadialMenuItem undoMenuItem = GetRadialMenuItem("Undo", "Undo", pathUndo);
            undoMenuItem.Command = UndoCommand;
            radialMenu.Items.Add(undoMenuItem);
            undoMenuItem = GetRadialMenuItem("Redo", "Redo", pathRedo);
            undoMenuItem.Command = RedoCommand;
            radialMenu.Items.Add(undoMenuItem);
        }
