        /// <summary>
        /// Gets the highlight color radial menu item.
        /// </summary>
        /// <returns></returns>
        private SfRadialMenuItem GetHighlightColorRadialMenuItem()
        {
            SfRadialMenuItem menuItem = new SfRadialMenuItem() { ToolTip = "Highlight Color", CheckMode = CheckMode.None, ToolTipPlacement = ToolTipPlacement.Top };
            Border border = new Border();
            border.Background = new SolidColorBrush(Colors.Transparent);
            border.Padding = new Thickness(5);
            StackPanel panel = new StackPanel();
            panel.Children.Add(XamlReader.Load(pathHighlight) as Windows.UI.Xaml.Shapes.Path);
            TextBlock textBlock = new TextBlock() { FontSize = 12, Margin = new Thickness(3), HorizontalAlignment = HorizontalAlignment.Center };
            textBlock.Text = "Highlight";
            panel.Children.Add(textBlock);
            border.Child = panel;
            menuItem.Header = border;
            //Adds Radial Color items
            SfRadialColorItem radialColorMenuItem = new SfRadialColorItem() { ToolTipPlacement = ToolTipPlacement.Top, Command = HighlightColorCommand, ToolTip = "No Color", CommandParameter = HighlightColor.NoColor, Color = Colors.White };
