        /// <summary>
        /// Gets the radial menu item.
        /// </summary>
        /// <param name="content">The content.</param>
        /// <param name="toolTip">The tool tip.</param>
        /// <param name="pathResource">The path resource.</param>
        /// <returns></returns>
        private SfRadialMenuItem GetRadialMenuItem(string content, string toolTip, string pathResource)
        {
            SfRadialMenuItem menuItem = new SfRadialMenuItem() { ToolTip = toolTip, CheckMode = CheckMode.None, ToolTipPlacement = ToolTipPlacement.Top };
            menuItem.Header = GetRadialMenuHeader(content, pathResource);
            return menuItem;
        }
        /// <summary>
        /// Gets the radial menu header.
        /// </summary>
        /// <param name="content">The content.</param>
        /// <param name="pathResource">The path resource.</param>
        /// <returns></returns>
        private Border GetRadialMenuHeader(string content, string pathResource)
        {
            Border border = new Border();
            border.Background = new SolidColorBrush(Colors.Transparent);
            border.Padding = new Thickness(5);
            StackPanel panel = new StackPanel() { HorizontalAlignment = HorizontalAlignment.Center, VerticalAlignment = VerticalAlignment.Center };
            panel.Children.Add(XamlReader.Load(pathResource) as Windows.UI.Xaml.Shapes.Path);
            TextBlock textBlock = new TextBlock() { FontSize = 11, Margin = new Thickness(3), TextWrapping = TextWrapping.Wrap};
            textBlock.Text = content;
            panel.Children.Add(textBlock);
            border.Child = panel;
            border.HorizontalAlignment = HorizontalAlignment.Center;
            border.VerticalAlignment = VerticalAlignment.Center;
            return border;
        }
