        /// <summary>
        /// Handles the TextChanged event of the displayTextBox control.
        /// </summary>
        /// <param name="sender">The source of the event.</param>
        /// <param name="e">The <see cref="TextChangedEventArgs"/> instance containing the event data.</param>
        void displayTextBox_TextChanged(object sender, TextChangedEventArgs e)
        {
            if (string.IsNullOrEmpty(displayTextBox.Text.Trim(' ')))
                isDisplayTextUpdated = false;
            else
                isDisplayTextUpdated = true;
        }
        /// <summary>
        /// Handles the TextChanged event of the urlTextBox control.
        /// </summary>
        /// <param name="sender">The source of the event.</param>
        /// <param name="e">The <see cref="TextChangedEventArgs"/> instance containing the event data.</param>
        void urlTextBox_TextChanged(object sender, TextChangedEventArgs e)
        {
            string navigationLink = urlTextBox.Text.Trim(' ');
            urlTextBox.TextChanged -= urlTextBox_TextChanged;
            if (navigationLink.ToLowerInvariant().StartsWith("www."))
            {
                urlTextBox.Text = navigationLink = "http://" + navigationLink;
                urlTextBox.SelectionStart = navigationLink.Length;
            }
            else if (navigationLink.Contains("@") && !navigationLink.ToLowerInvariant().StartsWith("mailto:"))
            {
                urlTextBox.Text = navigationLink = "mailto:" + navigationLink;
                urlTextBox.SelectionStart = navigationLink.Length;
            }
            else
            {
                int selectionStart = urlTextBox.SelectionStart;
                urlTextBox.Text = navigationLink;
                if (selectionStart > navigationLink.Length)
                    urlTextBox.SelectionStart = navigationLink.Length;
            }
            urlTextBox.TextChanged += urlTextBox_TextChanged;
            addHyperlinkButton.IsEnabled = !string.IsNullOrEmpty(navigationLink);
            if (!isDisplayTextUpdated)
            {
                displayTextBox.TextChanged -= displayTextBox_TextChanged;
                displayTextBox.Text = navigationLink;
                displayTextBox.TextChanged += displayTextBox_TextChanged;
            }
        }
        /// <summary>
        /// Shows the hyperlink UI async.
        /// </summary>
        internal void ShowHyperlinkUI()
        {
            hyperlinkGrid.Width = Window.Current.Bounds.Width;
            popup.HorizontalOffset = 0;
            popup.VerticalOffset = (Window.Current.Bounds.Height - 200) / 2;
            popup.Child = hyperlinkGrid;
            addHyperlinkButton.IsEnabled = false;
            LoadHyperlinkField();
            OpenPopup();
        }
        /// <summary>
        /// Loads the hyperlink field.
        /// </summary>
        private void LoadHyperlinkField()
        {
            FieldBeginAdv fieldBegin = Selection.GetHyperlinkField();
            if (fieldBegin != null)
            {
                string displayText = "";
                if (fieldBegin.FieldSeparator != null)
                {
                    bool isNestedField = false;
                    CharacterFormat format = null;
                    displayText = fieldBegin.FieldSeparator.OwnerParagraph.GetHyperlinkDisplayText(fieldBegin.FieldSeparator, fieldBegin.FieldEnd, ref isNestedField, ref format);
                    if (isNestedField)
                        displayTextBox.IsEnabled = false;
                }
                displayTextBox.Text = displayText;
                isDisplayTextUpdated = !string.IsNullOrEmpty(displayText.Trim(' '));
                Hyperlink hyperlink = new Hyperlink(fieldBegin);
                urlTextBox.Text = hyperlink.NavigationLink;
                addHyperlinkButton.IsEnabled = !string.IsNullOrEmpty(hyperlink.NavigationLink);
                if (!isDisplayTextUpdated)
                {
                    displayTextBox.TextChanged -= displayTextBox_TextChanged;
                    displayTextBox.Text = hyperlink.NavigationLink;
                    displayTextBox.TextChanged += displayTextBox_TextChanged;
                }
            }
        }
