        /// <summary>
        /// Opens the popup.
        /// </summary>
        private void OpenPopup()
        {
            IsGetPasswordUIOpened = true;
            popup.IsOpen = true;
            radialMenu.IsOpen = false;
            radialMenu.Visibility = Visibility.Collapsed;
            Viewer.HideCaret(false);
        }
        /// <summary>
        /// Closes the popup.
        /// </summary>
        private void ClosePopup()
        {
            IsGetPasswordUIOpened = false;
            popup.IsOpen = false;
            popup.ClearValue(Popup.ChildProperty);
            radialMenu.Visibility = Visibility.Visible;
        }
        /// <summary>
        /// Closes the hyperlink popup.
        /// </summary>
        private void CloseHyperlinkPopup()
        {
            ClosePopup();
            isDisplayTextUpdated = false;
            urlTextBox.ClearValue(TextBox.TextProperty);
            displayTextBox.ClearValue(TextBox.TextProperty);
            displayTextBox.ClearValue(TextBox.IsEnabledProperty);
        }
        /// <summary>
        /// Handles the Click event of the addHyperlinkButton control.
        /// </summary>
        /// <param name="sender">The source of the event.</param>
        /// <param name="e">The <see cref="RoutedEventArgs"/> instance containing the event data.</param>
        void addHyperlinkButton_Click(object sender, RoutedEventArgs e)
        {
            AddHyperlink();
        }
        /// <summary>
        /// Adds the hyperlink.
        /// </summary>
        private void AddHyperlink()
        {
            string url = urlTextBox.Text.Trim(' ');
            string displayText = displayTextBox.Text.Trim(' ');
            if (string.IsNullOrEmpty(displayText))
                displayText = url;
            //Inserts a hyperlink at current text position.
            if (!string.IsNullOrEmpty(url))
                selection.InsertHyperlink(url, displayText);
            CloseHyperlinkPopup();
        }
