        /// <summary>
        /// Provides the behavior for the Measure pass of the layout cycle. Classes can override this method to define their own Measure pass behavior.
        /// </summary>
        /// <param name="availableSize">The available size that this object can give to child objects. Infinity can be specified as a value to indicate that the object will size to whatever content is available.</param>
        /// <returns>
        /// The size that this object determines it needs during layout, based on its calculations of the allocated sizes for child objects or based on other considerations such as a fixed container size.
        /// </returns>
        protected override Size MeasureOverride(Size availableSize)
        {
            if (IsDocumentLoaded)
                CreateBlockOnEmpty();
            if (double.IsInfinity(availableSize.Width))
                availableSize.Width = 200;
            double width = availableSize.Width;
            if (LayoutType == LayoutType.Block)
                Visiblebounds = new Rect(Visiblebounds.X, Visiblebounds.Y, width, 0);
            else
            {
                if (double.IsInfinity(availableSize.Height))
                    //Preserves minimal height, if not defined.
                    availableSize.Height = 200;
                if (!double.IsInfinity(MaxHeight) && availableSize.Height > MaxHeight)
                    availableSize.Height = MaxHeight;
                if (MinHeight > 0 && availableSize.Height < MinHeight)
                    availableSize.Height = MinHeight;
                if (VerticalScrollBarVisibility)
                    width = width - (verticalScrollBar == null ? 17 : Math.Max(verticalScrollBar.Width, verticalScrollBar.MinWidth));
                Visiblebounds = new Rect(Visiblebounds.X, Visiblebounds.Y, width, availableSize.Height);
                if (LayoutType == LayoutType.Pages)
                {
                    Canvas.SetLeft(CurrentLoadingPagePopup, availableSize.Width - 180);
                    Canvas.SetTop(CurrentLoadingPagePopup, availableSize.Height - 80);
                }
            }
            return base.MeasureOverride(availableSize);
        }
        /// <summary>
        /// Validates the height.
        /// </summary>
        /// <param name="availableHeight">The available height.</param>
        /// <param name="contentHeight">The content height.</param>
        /// <returns></returns>
        internal double ValidateHeight(double availableHeight, double contentHeight)
        {
            if (double.IsNaN(Height))
            {
                if (MinHeight == 0 && double.IsInfinity(MaxHeight))
                    //Preserves content size, if the height is not defined.
                    availableHeight = contentHeight;
                else
                {
                    if (!double.IsInfinity(MaxHeight) && contentHeight < MaxHeight)
                        availableHeight = contentHeight;
                    if (MinHeight > 0 && availableHeight < MinHeight)
                        availableHeight = MinHeight;
                }
            }
            return availableHeight;
        }
