        protected override Size ArrangeOverride(Size finalSize)
        {
            return base.ArrangeOverride(finalSize);
        }
        /// <summary>
        /// Called before the GotFocus event occurs.
        /// </summary>
        /// <param name="e">The data for the event.</param>
        protected override void OnGotFocus(RoutedEventArgs e)
        {
            if (viewer != null && Document != null)
            {
                if (Selection.IsCleared && Selection.Start != null)
                    Selection.FireSelectionChanged(true);
                viewer.ShowCaret(false);
            }
            base.OnGotFocus(e);
        }
        /// <summary>
        /// Called before the LostFocus event occurs.
        /// </summary>
        /// <param name="e">The data for the event.</param>
        protected override void OnLostFocus(RoutedEventArgs e)
        {
#if !WPF
            //Sets core cursor to arrow type on focus lost from SfRichTextBoxAdv.
            Cursor = new CoreCursor(CoreCursorType.Arrow, 0);
#endif
            bool isFocused = IsChildFocused();
            if (!isFocused && viewer != null && Document != null)
                viewer.HideCaret(false);
            base.OnLostFocus(e);
        }
        /// <summary>
        /// Determines whether the child element of this instance is focused.
        /// </summary>
        /// <returns>
        ///   <c>true</c> if the child element of this instance is focused; otherwise, <c>false</c>.
        /// </returns>
        internal bool IsChildFocused()
        {
#if WPF
#else
            if (FocusState != FocusState.Unfocused)
                return true;
            if (IsGetPasswordUIOpened)
                return false;
            if (radialMenuNavigateButton != null && radialMenuNavigateButton.FocusState != FocusState.Unfocused)
                return true;
            if (horizontalScrollBar != null && horizontalScrollBar.FocusState != FocusState.Unfocused)
                return true;
            if (verticalScrollBar != null && verticalScrollBar.FocusState != FocusState.Unfocused)
                return true;
#endif
            return false;
        }
