        /// <summary>
        /// Gets the key modifier.
        /// </summary>
        /// <param name="key">The key.</param>
        /// <returns></returns>
        private VirtualKeyModifiers GetKeyModifier(VirtualKey key)
        {
            switch (key)
            {
                case VirtualKey.Application:
                    return VirtualKeyModifiers.Windows;
                case VirtualKey.Menu:
                    return VirtualKeyModifiers.Menu;
                case VirtualKey.Control:
                    return VirtualKeyModifiers.Control;
                case VirtualKey.Shift:
                    return VirtualKeyModifiers.Shift;
                default:
                    return VirtualKeyModifiers.None;
            }
        }
        /// <summary>
        /// Called before the KeyDown event occurs.
        /// </summary>
        /// <param name="e">The data for the event.</param>
        protected override void OnKeyDown(KeyRoutedEventArgs e)
        {
            if (IsGetPasswordUIOpened)
                return;
            if (coreWindow == null)
                coreWindow = CoreWindow.GetForCurrentThread();
            VirtualKeyModifiers modifier = GetKeyModifier(e.Key);
            if (modifier != VirtualKeyModifiers.None)
            {
                if (ModifierKey == VirtualKeyModifiers.None)
                    ModifierKey = modifier;
                else
                    ModifierKey |= modifier;
                return;
            }
            if (IsDocumentLoaded)
            {
                acceptCharacterReceived = true;
                coreWindow.CharacterReceived += coreWindow_CharacterReceived;
            }
            bool isHandled = true;
            if (ModifierKey == VirtualKeyModifiers.Control)
            {
                switch (e.Key)
                {
                    case (VirtualKey)187:
                        ZoomFactor += 10;
                        break;
                    case (VirtualKey)189:
                        ZoomFactor -= 10;
                        break;
                    case VirtualKey.Home:
                        Viewer.HandleControlHomeKey();
                        break;
                    case VirtualKey.End:
                        Viewer.HandleControlEndKey();
                        break;
                    case VirtualKey.Left:
                        Viewer.HandleControlLeftKey();
                        break;
                    case VirtualKey.Right:
                        Viewer.HandleControlRightKey();
                        break;
                    case VirtualKey.A:
                        Selection.SelectAll();
                        break;
                    case VirtualKey.Z:
                        History.Undo();
                        break;
                    case VirtualKey.Y:
                        History.Redo();
                        break;
                    case VirtualKey.B:
                        if (!IsReadOnlyMode && IsDocumentLoaded)
                            Selection.OnBold();
                        break;
                    case VirtualKey.I:
                        if (!IsReadOnlyMode && IsDocumentLoaded)
                            Selection.OnItalic();
                        break;
                    case VirtualKey.C:
                        Selection.Copy();
                        break;
                    case VirtualKey.X:
                        if (!IsReadOnlyMode && IsDocumentLoaded)
                            Selection.Cut();
                        break;
                    case VirtualKey.V:
                        if (!IsReadOnlyMode && IsDocumentLoaded)
                            Selection.Paste();
                        break;
                    case VirtualKey.U:
                        if (!IsReadOnlyMode && isDocumentLoaded)
                            Selection.ToggleUnderline();
                        break;
                    case VirtualKey.K:
                        if (!IsReadOnlyMode && isDocumentLoaded)
                            ShowHyperlinkUI();
                        break;
                    case VirtualKey.Tab:
                        Viewer.HandleTabKey(selection, false);
                        break;
                    default:
                        isHandled = false;
                        break;
                }
            }
            else if (ModifierKey == VirtualKeyModifiers.Shift)
            {
                switch (e.Key)
                {
                    case VirtualKey.Left:
                        Viewer.HandleShiftLeftKey();
                        break;
                    case VirtualKey.Up:
                        Viewer.HandleShiftUpKey();
                        break;
                    case VirtualKey.Right:
                        Viewer.HandleShiftRightKey();
                        break;
                    case VirtualKey.Down:
                        Viewer.HandleShiftDownKey();
                        break;
                    case VirtualKey.Home:
                        viewer.HandleShiftHomeKey();
                        break;
                    case VirtualKey.End:
                        viewer.HandleShiftEndKey();
                        break;
                    case VirtualKey.Tab:
                        viewer.HandleShiftTabKey(Selection);
                        break;
                    default:
                        isHandled = false;
                        break;
                }
            }
            else if (ModifierKey == VirtualKeyModifiers.None)
            {
                switch (e.Key)
                {
                    case VirtualKey.PageUp:
                        verticalScrollBar.Value -= viewer.Visiblebounds.Height;
                        break;
                    case VirtualKey.PageDown:
                        verticalScrollBar.Value += viewer.Visiblebounds.Height;
                        break;
                    case VirtualKey.Right:
                        Viewer.HandleRightKey();
                        break;
                    case VirtualKey.Left:
                        Viewer.HandleLeftKey();
                        break;
                    case VirtualKey.Up:
                        Viewer.HandleUpKey();
                        break;
                    case VirtualKey.Down:
                        Viewer.HandleDownKey();
                        break;
                    case VirtualKey.Enter:
                        if (!IsReadOnlyMode && IsDocumentLoaded)
                            Viewer.HandleEnterKey();
                        break;
                    case VirtualKey.Back:
                        if (!IsReadOnlyMode && IsDocumentLoaded)
                            Viewer.HandleBackKey();
                        break;
                    case VirtualKey.Delete:
                        if (!IsReadOnlyMode && IsDocumentLoaded)
                            Viewer.HandleDeleteKey();
                        break;
                    case VirtualKey.Escape:
                        if (fontPopup.Visibility == Visibility.Visible)
                        {
                            IsPopItemVisible = false;
                            fontPopup.Visibility = Visibility.Collapsed;
                        }
                        else
                            isHandled = false;
                        break;
                    case VirtualKey.Home:
                        viewer.HandleHomeKey();
                        break;
                    case VirtualKey.End:
                        viewer.HandleEndKey();
                        break;
                    case VirtualKey.Tab:
                        viewer.HandleTabKey(selection, true);
                        break;
                    default:
                        isHandled = false;
                        break;
                }
            }
            else if (ModifierKey == (VirtualKeyModifiers.Shift | VirtualKeyModifiers.Control))
            {
                switch (e.Key)
                {
                    case VirtualKey.Home:
                        Viewer.HandleControlShiftHomeKey();
                        break;
                    case VirtualKey.End:
                        Viewer.HandleControlShiftEndKey();
                        break;
                    case VirtualKey.Left:
                        Viewer.HandleShiftLeftKey();
                        break;
                    case VirtualKey.Up:
                        Viewer.HandleShiftUpKey();
                        break;
                    case VirtualKey.Right:
                        Viewer.HandleShiftRightKey();
                        break;
                    case VirtualKey.Down:
                        Viewer.HandleShiftDownKey();
                        break;
                    default:
                        isHandled = false;
                        break;
                }
            }
            else
                isHandled = false;
            if (isHandled)
            {
                e.Handled = true;
                if (acceptCharacterReceived)
                {
                    acceptCharacterReceived = false;
                    coreWindow.CharacterReceived -= coreWindow_CharacterReceived;
                }
            }
            base.OnKeyDown(e);
        }
        /// <summary>
        /// Called before the KeyUp event occurs.
        /// </summary>
        /// <param name="e">The data for the event.</param>
        protected override void OnKeyUp(KeyRoutedEventArgs e)
        {
            if (IsGetPasswordUIOpened)
                return;
            VirtualKeyModifiers modifier = GetKeyModifier(e.Key);
            if (modifier != VirtualKeyModifiers.None)
                ModifierKey &= ~modifier;
            if (ModifierKey != VirtualKeyModifiers.None)
            {
                if ((ModifierKey & VirtualKeyModifiers.Control) == VirtualKeyModifiers.Control
                    && coreWindow.GetKeyState(VirtualKey.Control) == CoreVirtualKeyStates.None)
                    ModifierKey &= ~VirtualKeyModifiers.Control;
                if ((ModifierKey & VirtualKeyModifiers.Menu) == VirtualKeyModifiers.Menu
                    && coreWindow.GetKeyState(VirtualKey.Menu) == CoreVirtualKeyStates.None)
                    ModifierKey &= ~VirtualKeyModifiers.Menu;
                if ((ModifierKey & VirtualKeyModifiers.Shift) == VirtualKeyModifiers.Shift
                    && coreWindow.GetKeyState(VirtualKey.Shift) == CoreVirtualKeyStates.None)
                    ModifierKey &= ~VirtualKeyModifiers.Shift;
                if ((ModifierKey & VirtualKeyModifiers.Windows) == VirtualKeyModifiers.Windows
                    && coreWindow.GetKeyState(VirtualKey.Application) == CoreVirtualKeyStates.None)
                    ModifierKey &= ~VirtualKeyModifiers.Windows;
            }
        }
        /// <summary>
        /// Raised when mouse left button is clicked
        /// </summary>
        /// <param name="sender">The sender.</param>
        /// <param name="args">The <see cref="CharacterReceivedEventArgs"/> instance containing the event data.</param>
        private void coreWindow_CharacterReceived(CoreWindow sender, CharacterReceivedEventArgs args)
        {
            if ((ModifierKey & VirtualKeyModifiers.Control) == VirtualKeyModifiers.Control)
                return;
            if (coreWindow == null)
                (sender as CoreWindow).CharacterReceived -= coreWindow_CharacterReceived;
            else
                coreWindow.CharacterReceived -= coreWindow_CharacterReceived;
            if (!acceptCharacterReceived)
                return;
            acceptCharacterReceived = false;
            char character = Convert.ToChar(args.KeyCode);
            OnTextInput(character);
        }
        /// <summary>
        /// Called when text input.
        /// </summary>
        /// <param name="character">The character.</param>
        private async void OnTextInput(char character)
        {
            if (character.ToString() != "\r" && character.ToString() != "\b" && !IsReadOnlyMode && IsDocumentLoaded)
            {
                await Dispatcher.RunAsync(CoreDispatcherPriority.Normal, delegate()
                {
                    Viewer.HandleTextInput(character.ToString());
                });
            }
        }
