        /// <summary>
        /// Called before the PointerPressed event occurs.
        /// </summary>
        /// <param name="e">Event data for the event.</param>
        protected override void OnPointerPressed(PointerRoutedEventArgs e)
        {
            if (IsGetPasswordUIOpened)
                return;
            if (CopyIcon.Visibility == Visibility.Visible)
            {
                PointerPoint pointerPoint = e.GetCurrentPoint(CopyIcon);
                if (pointerPoint.Position.X >= 0 && pointerPoint.Position.X <= CopyIcon.ActualWidth
                    && pointerPoint.Position.Y >= 0 && pointerPoint.Position.Y <= CopyIcon.ActualHeight)
                {
                    e.Handled = true;
                    IsPopItemVisible = false;
                    CopyIcon.Visibility = Visibility.Collapsed;
                    Selection.Copy();
                    base.OnPointerPressed(e);
                    return;
                }
            }
            if (radialMenu.IsOpen)
            {
                PointerPoint pointerPoint = e.GetCurrentPoint(radialMenu);
                if (pointerPoint.Position.X >= 0 && pointerPoint.Position.X <= radialMenu.ActualWidth
                    && pointerPoint.Position.Y >= 0 && pointerPoint.Position.Y <= radialMenu.ActualHeight)
                {
                    e.Handled = true;
                    base.OnPointerPressed(e);
                    return;
                }
                radialMenu.IsOpen = false;
            }
            UpdateInputMode(e.Pointer.PointerDeviceType, false);
            viewer.OnPointerPressed(e);
            e.Handled = true;
            base.OnPointerPressed(e);
        }
