        /// <summary>
        /// Called before the PointerMoved event occurs.
        /// </summary>
        /// <param name="e">Event data for the event.</param>
        protected override void OnPointerMoved(PointerRoutedEventArgs e)
        {
            if (IsImageResizing || IsGetPasswordUIOpened)
                return;
            UpdateInputMode(e.Pointer.PointerDeviceType, true);
            if (verticalScrollBar.Visibility == Visibility.Visible)
            {
                UpdateCursor = true;
                Point point = e.GetCurrentPoint(verticalScrollBar).Position;
                Rect rect = new Rect(0, 0, verticalScrollBar.ActualWidth, verticalScrollBar.ActualHeight);
                if (rect.Contains(point))
                {
                    Cursor = new CoreCursor(CoreCursorType.Arrow, 0);
                    UpdateCursor = false;
                }
            }
            if (horizontalScrollBar.Visibility == Visibility.Visible)
            {
                UpdateCursor = true;
                Point point = e.GetCurrentPoint(horizontalScrollBar).Position;
                Rect rect = new Rect(0, 0, horizontalScrollBar.ActualWidth, horizontalScrollBar.ActualHeight);
                if (rect.Contains(point))
                {
                    Cursor = new CoreCursor(CoreCursorType.Arrow, 0);
                    UpdateCursor = false;
                }
            }
            if (radialMenu.Visibility == Visibility.Visible)
            {
                UpdateCursor = true;
                Point point = e.GetCurrentPoint(radialMenu).Position;
                double radialMenuSize = radialMenu.IsOpen ? radialMenu.ActualWidth : 60;
                Rect rect = new Rect((radialMenu.ActualWidth - radialMenuSize) / 2, (radialMenu.ActualHeight - radialMenuSize) / 2, radialMenuSize, radialMenuSize);
                if (rect.Contains(point))
                {
                    Cursor = new CoreCursor(CoreCursorType.Arrow, 0);
                    UpdateCursor = false;
                }
            }
            viewer.OnPointerMoved(e);
            UpdateCursor = true;
            base.OnPointerMoved(e);
        }
