        /// <summary>
        /// Updates the input mode.
        /// </summary>
        /// <param name="pointerDeviceType">Type of the pointer device.</param>
        private void UpdateInputMode(PointerDeviceType pointerDeviceType, bool isPointerMove)
        {
            if (pointerDeviceType == PointerDeviceType.Mouse)
            {
                IsTouchInput = false;
                if (horizontalScrollBar != null)
                    horizontalScrollBar.IndicatorMode = ScrollingIndicatorMode.MouseIndicator;
                if (verticalScrollBar != null)
                    verticalScrollBar.IndicatorMode = ScrollingIndicatorMode.MouseIndicator;
                if (viewer is LayoutViewer && !isPointerMove)
                    viewer.ImageResizer.InitResizeMarks();
            }
            else
            {
                IsTouchInput = true;
                if (horizontalScrollBar != null)
                    horizontalScrollBar.IndicatorMode = ScrollingIndicatorMode.TouchIndicator;
                if (verticalScrollBar != null)
                    verticalScrollBar.IndicatorMode = ScrollingIndicatorMode.TouchIndicator;
                if (viewer is LayoutViewer && !isPointerMove)
                    viewer.ImageResizer.InitTouchResizeMarks();
            }
        }
