        /// <summary>
        /// Gets the DocIO format type.
        /// </summary>
        /// <param name="formatType">Type of the format.</param>
        /// <returns></returns>
        private static DocIO.FormatType GetDocIOFormatType(FormatType formatType)
        {
            switch (formatType)
            {
                case FormatType.Doc:
                    return DocIO.FormatType.Doc;
                case FormatType.Docx:
                    return DocIO.FormatType.Word2013;
                case FormatType.Rtf:
                    return DocIO.FormatType.Rtf;
                case FormatType.Txt:
                    return DocIO.FormatType.Txt;
                default:
                    return DocIO.FormatType.Rtf;
            }
        }
