        /// <summary>
        /// Creates the empty document.
        /// </summary>
        /// <returns></returns>
        private DocIO.DLS.WordDocument CreateEmptyDocument()
        {
            DocIO.DLS.WordDocument doc = new DocIO.DLS.WordDocument();
            doc.EnsureMinimal();
            doc.LastSection.PageSetup.PageSize = new DocIO.DLS.SizeF(612, 792);
            doc.LastSection.PageSetup.Margins = new DocIO.DLS.MarginsF(72, 72, 72, 72);
            return doc;
        }
        /// <summary>
        /// Loads the document io internal.
        /// </summary>
        /// <param name="documentStream">The document stream.</param>
        /// <param name="formatType">Type of the format.</param>
        /// <returns></returns>
        private DocIO.DLS.WordDocument LoadDocIOInternal(Stream documentStream, FormatType formatType)
        {
#if DEBUG
            DateTime startTime = DateTime.Now;
#endif
            DocIO.DLS.WordDocument doc = null;
            if (documentStream != null)
            {
                DocIO.FormatType docIOFormatType = GetDocIOFormatType(formatType);
                Exception exception = null;
                try
                {
                    if (documentStream.Length == 0)
                        doc = CreateEmptyDocument();
                    else
                        doc = new DocIO.DLS.WordDocument(documentStream, docIOFormatType);
#if DEBUG
                    //Updates the time taken for loading Word document by DocIO.
                    PerformanceInfo.DocIOLoadTime = DateTime.Now - startTime;
#endif
                }
                catch (Exception ex)
                {
                    exception = ex;
                }
                if (exception != null)
                {
                    if (exception.Message.Contains("Document is encrypted"))
                    {
                        docFormatType = docIOFormatType;
                        documentStream.Position = 0;
                        encryptedStream = new MemoryStream();
                        documentStream.CopyTo(encryptedStream);
                        documentStream.Dispose();
                        //Gets the password from user.
                        ShowPasswordUI();
                    }
                    else
                    {
                        //Trigger event handler to handle the error occured on loading document.
                        FireFileLoadingFailed(exception);
                        throw new Exception(exception.Message, exception);
                    }
                }
            }
            return doc;
        }
        /// <summary>
        /// Loads the doc IO internal async.
        /// </summary>
        /// <param name="documentStream">The document stream.</param>
        /// <param name="formatType">Type of the format.</param>
        /// <returns></returns>
        private async Task<DocIO.DLS.WordDocument> LoadDocIOInternalAsync(Stream documentStream, FormatType formatType)
        {
            TaskCompletionSource<DocIO.DLS.WordDocument> tcs = new TaskCompletionSource<DocIO.DLS.WordDocument>();
#if DEBUG
            DateTime startTime = DateTime.Now;
#endif
            DocIO.DLS.WordDocument doc = null;
            if (documentStream != null)
            {
                DocIO.FormatType docIOFormatType = GetDocIOFormatType(formatType);
                Exception exception = null;
                try
                {
                    if (documentStream.Length == 0)
                        doc = CreateEmptyDocument();
                    else
                        doc = new DocIO.DLS.WordDocument(documentStream, docIOFormatType);
                }
                catch (Exception ex)
                {
                    exception = ex;
                }
                if (exception != null)
                {
                    if (exception.Message.Contains("Document is encrypted"))
                    {
                        //Gets the password from user.
                        string password = await ShowPasswordUIAsync();
                        if (password != null)
                        {
                            exception = null;
                            try
                            {
                                documentStream.Position = 0;
                                doc = new DocIO.DLS.WordDocument(documentStream, docIOFormatType, password);
                            }
                            catch (Exception ex)
                            {
                                exception = ex;
                            }
                            if (exception != null)
                            {
                                documentStream.Dispose();
                                if (exception.Message.Contains("Specified password \"" + password + "\" is incorrect!"))
                                    await ShowIncorrectPasswordAsync();
                                else
                                {
                                    //Trigger event handler to handle the error occured on loading document.
                                    FireFileLoadingFailed(exception);
                                    throw new Exception(exception.Message, exception);
                                }
                            }
                        }
                        else
                            documentStream.Dispose();
                    }
                    else
                    {
                        //Trigger event handler to handle the error occured on loading document.
                        FireFileLoadingFailed(exception);
                        throw new Exception(exception.Message, exception);
                    }
                }
#if DEBUG
                //Updates the time taken for loading Word document by DocIO.
                PerformanceInfo.DocIOLoadTime = DateTime.Now - startTime;
                PerformanceInfo.RenderingStartTime = DateTime.Now;
#endif
            }
            tcs.SetResult(doc);
            return await tcs.Task;
        }
#endif
        /// <summary>
        /// Determines whether the specified format type is supported format.
        /// </summary>
        /// <param name="formatType">Type of the format.</param>
        /// <returns>
        ///   <c>true</c> if the specified format type is supported format; otherwise, <c>false</c>.
        /// </returns>
        private bool IsSupportedFormat(FormatType formatType)
        {
            switch (formatType)
            {
                case FormatType.Doc:
                case FormatType.Docx:
                case FormatType.Rtf:
                case FormatType.Txt:
                    return true;
                default:
                    return false;
            }
        }
