        /// Saves the document to stream.
        /// </summary>
        /// <param name="stream">The stream.</param>
        /// <param name="formatType">Type of the format.</param>
        /// <returns></returns>
        private async Task<bool> SaveAsyncInternal(Stream stream, FormatType formatType)
        {
            TaskCompletionSource<bool> tcs = new TaskCompletionSource<bool>();
            await Task.Run(() =>
            {
                try
                {
                    SaveInternal(stream, formatType);
                    tcs.SetResult(true);
                }
                catch (Exception exp)
                {
                    tcs.SetException(exp);
                }
            });
            return await tcs.Task;
        }
        /// <summary>
        /// Saves the document to stream.
        /// </summary>
        /// <param name="documentStream">The document stream.</param>
        /// <param name="formatType">Type of the format.</param>
        /// <exception cref="System.NotSupportedException">RichTextBoxAdv does not support this file format.</exception>
        private void SaveInternal(Stream documentStream, FormatType formatType)
        {
            switch (formatType)
            {
                case FormatType.Doc:
                case FormatType.Docx:
                case FormatType.Rtf:
                case FormatType.Txt:
                    DocumentAdv documentAdv = null;
#if !WPF
                    UIDispatcher.Execute(() =>
                    {
#endif
                        documentAdv = this.Document;
#if !WPF
                    });
#endif
                    DocxExporting.ConvertToDocument(documentAdv, documentStream, formatType);
                    break;
                default:
                    throw new NotSupportedException("RichTextBoxAdv does not support this file format.");
            }
        }
#endif
        /// <summary>
        /// Exports to text.
        /// </summary>
        /// <param name="textStream">The text stream.</param>
        internal void ExportToText(Stream textStream)
        {
            TextExporting.ConvertToText(this.Document, textStream);
        }
        /// <summary>
        /// Exports to XAML.
        /// </summary>
        /// <param name="xamlStream">The xaml stream.</param>
        internal void ExportToXAML(Stream xamlStream)
        {
            XAMLExporting.ConvertToXAML(this.Document, xamlStream);
        }
