        /// <summary>
        /// Creates the blank document
        /// </summary>
        internal void CreateBlankDocument()
        {
            if (Document != null)
            {
                //Creates blank document.
                Document = new DocumentAdv();
                SectionAdv section = new SectionAdv();
                Document.Sections.Add(section);
                section.Blocks.Add(new ParagraphAdv());
                History.ClearHistory();
                Selection.ClearSelection();
            }
            else
                CreateBlockOnEmpty();
        }
        /// <summary>
        /// Creates the minimum block on empty.
        /// </summary>
        internal void CreateBlockOnEmpty()
        {
            if (Document == null)
                Document = new DocumentAdv();
            if (Document.Sections.Count == 0)
                Document.Sections.Add(new SectionAdv());
            if (Document.Sections[0].Blocks.Count == 0)
                Document.Sections[0].Blocks.Add(new ParagraphAdv());
        }
