        internal void OnViewerChanged(LayoutViewer viewer)
        {
            IsControlLoaded = false;
            if (contentPresenter != null)
                contentPresenter.Content = viewer;
            Visiblebounds = new Rect();
            UpdateEditorLayout();
            if (Selection.Start != null)
            {
                Selection.UpdatePhysicalPosition();
                Selection.FireSelectionChanged(true);
            }
