        /// <param name="format">The format.</param>
        /// <returns></returns>
        /// <exception cref="System.NotSupportedException">RichTextBoxAdv does not support this file format.</exception>
        internal FormatType GetFormatType(string format)
        {
            switch (format.ToLower())
            {
                case ".dotx":
                case ".docx":
                case ".docm":
                case ".dotm":
                    return FormatType.Docx;
                case ".dot":
                case ".doc":
                    return FormatType.Doc;
                case ".rtf":
                    return FormatType.Rtf;
                case ".txt":
                    return FormatType.Txt;
                default:
                    throw new NotSupportedException("RichTextBoxAdv does not support this file format.");
            }
        }
