        /// <summary>
        /// Gets the bitmap image.
        /// </summary>
        /// <param name="resourceFile">The resource file.</param>
        /// <returns></returns>
        internal BitmapImage GetBitmapImage(string resourceFile)
        {
            BitmapImage bitmapImage = new BitmapImage();
#if !WPF
            Assembly assembly = typeof(SfRichTextBoxAdv).GetTypeInfo().Assembly;
            Stream imageStream = assembly.GetManifestResourceStream(resourceFile);
            if (imageStream != null)
            {
                InMemoryRandomAccessStream randomAccessStream = new InMemoryRandomAccessStream();
                Stream stream = randomAccessStream.AsStreamForWrite();
                imageStream.Position = 0;
                //Copies the data to random access stream.
                imageStream.CopyTo(stream);
                stream.Position = 0;
                bitmapImage.SetSource(randomAccessStream);
            }
#endif
            return bitmapImage;
        }
        #endregion

        #region Dispose
        /// <summary>
        /// Releases unmanaged and - optionally - managed resources.
        /// </summary>
        public void Dispose()
        {
#if !WPF
            //Sets core cursor to arrow type on focus lost from SfRichTextBoxAdv.
            Cursor = new CoreCursor(CoreCursorType.Arrow, 0);
            if (coreWindow != null)
            {
                if (acceptCharacterReceived)
                    coreWindow.CharacterReceived -= coreWindow_CharacterReceived;
                coreWindow = null;
            }
            acceptCharacterReceived = false;
            radialMenuNavigateButton = null;
            radialMenu.Opened -= radialMenu_Opened;
            radialMenu.Closed -= radialMenu_Closed;
            radialMenu.GotFocus -= radialMenu_GotFocus;
            popup.Opened -= popup_Opened;
            popup.Closed -= popup_Closed;
            popup.KeyDown -= popup_KeyDown;
            urlTextBox.TextChanged -= urlTextBox_TextChanged;
            displayTextBox.TextChanged -= displayTextBox_TextChanged;
            addHyperlinkButton.Click -= addHyperlinkButton_Click;
            cancelHyperlinkButton.Click -= cancelHyperlinkButton_Click;
            if (passwordGrid != null)
            {
                passwordGrid.Children.Clear();
                passwordGrid = null;
            }
            passwordBox = null;
            GetPasswordTCS = null;
#endif
            if (viewer != null)
            {
                viewer.ClearContainer();
                viewer.Dispose();
                viewer = null;
                contentPresenter.ClearValue(ContentControl.ContentProperty);
                if (horizontalScrollBar.Parent != null)
                    (horizontalScrollBar.Parent as Panel).Children.Remove(horizontalScrollBar);
                if (verticalScrollBar.Parent != null)
                    (verticalScrollBar.Parent as Panel).Children.Remove(verticalScrollBar);
            }
#if !WPF
            printDocumentInternal = null;
#endif
            if (history != null)
            {
                history.Dispose();
                history = null;
            }
            if (selection != null)
            {
                selection.Dispose();
                selection = null;
            }
            if (Document != null)
                Document.Dispose();
        }
        #endregion
    }
